// ------------------------------------------------------------------
//  Design Unit:    matrix_multiply_core_core_fsm
//  FSM Module
// ------------------------------------------------------------------


module matrix_multiply_core_core_fsm (
  clk, rst, fsm_output, ROW_C_0_tr0
);
  input clk;
  input rst;
  output [2:0] fsm_output;
  reg [2:0] fsm_output;
  input ROW_C_0_tr0;


  // FSM State Type Declaration for matrix_multiply_core_core_fsm_1
  parameter
    main_C_0 = 2'd0,
    ROW_C_0 = 2'd1,
    main_C_1 = 2'd2;

  reg [1:0] state_var;
  reg [1:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations 
  always @(*)
  begin : matrix_multiply_core_core_fsm_1
    case (state_var)
      ROW_C_0 : begin
        fsm_output = 3'b010;
        if ( ROW_C_0_tr0 ) begin
          state_var_NS = main_C_1;
        end
        else begin
          state_var_NS = ROW_C_0;
        end
      end
      main_C_1 : begin
        fsm_output = 3'b100;
        state_var_NS = main_C_0;
      end
      // main_C_0
      default : begin
        fsm_output = 3'b001;
        state_var_NS = ROW_C_0;
      end
    endcase
  end

  always @(posedge clk) begin
    if ( rst ) begin
      state_var <= main_C_0;
    end
    else begin
      state_var <= state_var_NS;
    end
  end

endmodule

